package com.posdesktop.pos.fiscal;
import static com.posdesktop.pos.fiscal.FiscalUi.*;
import com.posdesktop.pos.integration.*;
import javafx.beans.property.*;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.stage.FileChooser;
import java.nio.file.*;
import java.util.UUID;

public final class FiscalDeliveryPane extends VBox {
 private final PosApiClient api;private final String id,number;private final boolean mayEdit;
 private final BooleanProperty busy=new SimpleBooleanProperty(),ready=new SimpleBooleanProperty(),sent=new SimpleBooleanProperty();
 private final ComboBox<Choice> paper=choices("MM80","Termico 80 mm","MM58","Termico 58 mm","A4","Hoja A4");
 private final TextField email=field("fiscal-delivery-email","Correo del destinatario de prueba");private final Label status=note("Cargando entrega…"),mode=note("");
 private final TextArea evidence=new TextArea();private final Button send=button("Simular correo · F9",true),savePdf=button("Guardar PDF · F7",false),print=button("Imprimir · F8",false),bundle=button("Guardar paquete ZIP",false),refresh=button("Actualizar · F10",false),newMail=button("Nueva entrega",false);
 private String requestId=UUID.randomUUID().toString();private boolean initialized;
 public FiscalDeliveryPane(PosApiClient api,String id,String number,boolean mayEdit){super(14);this.api=api;this.id=id;this.number=number;this.mayEdit=mayEdit;setId("fiscal-delivery-pane");status.setId("fiscal-delivery-status");send.setId("fiscal-delivery-send");savePdf.setId("fiscal-delivery-pdf");paper.setId("fiscal-delivery-paper");paper.getSelectionModel().selectFirst();
  for(var button:new Button[]{savePdf,print,bundle,newMail})button.disableProperty().bind(busy.or(ready.not()));refresh.disableProperty().bind(busy);send.disableProperty().bind(busy.or(ready.not()).or(sent).or(new SimpleBooleanProperty(!mayEdit)));paper.disableProperty().bind(busy);email.disableProperty().bind(busy);
  evidence.setEditable(false);evidence.setWrapText(true);evidence.setPrefRowCount(12);evidence.getStyleClass().add("soft-area");evidence.setAccessibleText("Historial de correos y validacion de respuestas DIAN");
  getChildren().addAll(card("PDF y entrega de prueba",note("Documentos de prueba, sin validez fiscal. El PDF conserva los datos del XML guardado. El correo requiere una accion explicita; no se envia al abrir esta vista."),row(group("Papel para PDF e impresion",paper,240),savePdf,print,bundle),mode,row(group("Destinatario",email,400),send,newMail,refresh),status,evidence));
  savePdf.setOnAction(e->save(false));bundle.setOnAction(e->save(true));print.setOnAction(e->print());refresh.setOnAction(e->load());newMail.setOnAction(e->{requestId=UUID.randomUUID().toString();sent.set(false);email.requestFocus();});
  email.textProperty().addListener((o,a,b)->{if(initialized&&!busy.get()){requestId=UUID.randomUUID().toString();sent.set(false);}});
  send.setOnAction(e->{String recipient=email.getText().trim();if(recipient.isEmpty()){status(status,"Ingresa el correo del destinatario de prueba.",true);email.requestFocus();return;}work("Procesando entrega de prueba…");var request=new PosApiClient.FiscalMailRequest(requestId,recipient,selected(paper));async(()->api.enviarCorreoFiscal(id,request),r->{busy.set(false);sent.set(true);status(status,r.message(),"INCIERTO".equals(r.state()));load();},this::failure);});
  addEventFilter(javafx.scene.input.KeyEvent.KEY_PRESSED,e->{Button action=switch(e.getCode()){case F7->savePdf;case F8->print;case F9->send;case F10->refresh;default->null;};if(action!=null){if(!action.isDisabled())action.fire();e.consume();}});load();
 }
 private void load(){work("Cargando historial y verificacion…");async(()->api.prepararEntregaFiscal(id),r->{busy.set(false);ready.set(true);mode.setText("Modo de correo: "+r.mode()+". "+("SMTP".equals(r.mode())?"Se enviara un correo real de PRUEBAS al destinatario indicado.":"Simulacion local, sin enviar mensajes."));send.setText("SMTP".equals(r.mode())?"Enviar prueba SMTP · F9":"Simular correo · F9");if(!initialized){email.setText(r.recipient());initialized=true;}StringBuilder text=new StringBuilder();for(var v:r.responses()){var s=v.signature();text.append(v.mode()).append(" · Firma: ").append(s.signatureValid()?"integra":"no verificable").append(" · Documento: ").append(s.correlated()?"coincide":"no correlacionado").append(" · Certificado: ").append(s.trusted()?"huella confiable configurada":"sin confianza configurada").append('\n');s.issues().forEach(issue->text.append("  ").append(issue).append('\n'));}if(r.responses().isEmpty())text.append("Sin ApplicationResponse disponible para verificar.\n");for(var mail:r.history())text.append('\n').append(mail.createdAt()).append(" · ").append(mail.state()).append(" · ").append(mail.recipient()).append('\n').append(mail.message()).append("\nSolicitud: ").append(mail.id()).append("\nSHA-256 del paquete: ").append(mail.bundleHash()).append('\n');evidence.setText(text.toString());status(status,r.history().isEmpty()?"Sin entregas. Puedes guardar el PDF o probar el envio por correo.":"Historial actualizado. Consulta abajo el resultado de cada entrega.",false);},this::failure);}
 private void save(boolean zip){var chooser=new FileChooser();chooser.setInitialFileName("PRUEBAS-"+number.replaceAll("[^A-Za-z0-9_-]","_")+(zip?".zip":".pdf"));var file=chooser.showSaveDialog(getScene().getWindow());if(file==null)return;String format=selected(paper);work("Guardando archivo…");async(()->{byte[] bytes=api.descargarArchivoFiscal(id,format,zip);try{Files.write(file.toPath(),bytes);return true;}catch(Exception e){throw new IllegalStateException("No se pudo guardar el archivo.");}},r->{busy.set(false);status(status,"Archivo de prueba guardado.",false);},this::failure);}
 private void print(){String format=selected(paper);work("Preparando impresion a tamano real…");async(()->{Path file=null;try{file=Files.createTempFile("pos-fiscal-prueba-",".pdf");Files.write(file,api.descargarArchivoFiscal(id,format,false));return new FiscalPdfPrinter().print(file,number);}catch(Exception e){throw new IllegalStateException(e.getMessage());}finally{if(file!=null)try{Files.deleteIfExists(file);}catch(Exception ignored){}}},printer->{busy.set(false);status(status,"Documento de prueba enviado a la cola de "+printer+".",false);},this::failure);}
 private void work(String text){busy.set(true);status(status,text,false);}private void failure(RuntimeException e){busy.set(false);status(status,e.getMessage()+" Actualiza el historial antes de repetir un correo.",true);}
}
